parameters.jsCode:
// ============================================================
// Calculate Refund Chargeback Metrics
// Deterministic rolling 7-day ratio vs 90-day baseline.
// Gemini must NOT be used for anomaly decisions.
// ============================================================

const THRESHOLD_FALLBACK = 2;

function parseDate(value) {
  if (value === null || value === undefined || value === '') return null;
  if (Object.prototype.toString.call(value) === '[object Date]' && !Number.isNaN(value.getTime())) {
    return new Date(Date.UTC(value.getUTCFullYear(), value.getUTCMonth(), value.getUTCDate()));
  }
  const raw = String(value).trim();
  const m = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) {
    return new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])));
  }
  const d = new Date(raw);
  if (Number.isNaN(d.getTime())) return null;
  return new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
}

function parseAmount(value) {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number') {
    return Number.isFinite(value) && value >= 0 ? Number(value) : null;
  }
  const cleaned = String(value).trim().replace(/[$,]/g, '');
  if (!cleaned) return null;
  const n = Number(cleaned);
  if (!Number.isFinite(n) || n < 0) return null;
  return n;
}

function toDayKey(date) {
  return date.toISOString().slice(0, 10);
}

function addDays(date, days) {
  const d = new Date(date.getTime());
  d.setUTCDate(d.getUTCDate() + days);
  return d;
}

function round4(n) {
  return Number(Number(n).toFixed(4));
}

let thresholdMultiplier = THRESHOLD_FALLBACK;
try {
  const cfg = $('Configure Monitor Settings').first().json;
  if (cfg && cfg.thresholdMultiplier !== undefined && cfg.thresholdMultiplier !== null && cfg.thresholdMultiplier !== '') {
    const parsed = Number(cfg.thresholdMultiplier);
    if (Number.isFinite(parsed) && parsed > 0) thresholdMultiplier = parsed;
  }
} catch (e) {
  // Config node unavailable — use fallback
}

const salesItems = $('Read Sales Data').all();
const refundItems = $('Read Refund Chargeback Data').all();

const salesRows = salesItems.map((i) => i.json).filter((r) => r && Object.keys(r).length);
const refundRows = refundItems.map((i) => i.json).filter((r) => r && Object.keys(r).length);

let monitoringDateRaw = new Date().toISOString().slice(0, 10);
try {
  const cfgDate = $('Configure Monitor Settings').first().json.monitoringDateOverride;
  if (cfgDate && String(cfgDate).trim()) {
    monitoringDateRaw = String(cfgDate).trim();
  }
} catch (e) {}
const monitoringDate = parseDate(monitoringDateRaw);
if (!monitoringDate) {
  throw new Error('Invalid monitoringDateOverride. Use YYYY-MM-DD or leave blank.');
}
const currentWindowEnd = monitoringDate;
const currentWindowStart = addDays(monitoringDate, -6);
const historicalWindowEnd = addDays(monitoringDate, -7);
const historicalWindowStart = addDays(monitoringDate, -96);

const seenSales = new Set();
const sales = [];
for (const row of salesRows) {
  const date = parseDate(row.Date ?? row.date);
  const amount = parseAmount(row.Amount ?? row.amount);
  const orderId = String(row['Order ID'] ?? row.orderId ?? row.order_id ?? '').trim();
  if (!date || amount === null) continue;
  const key = `${toDayKey(date)}|${orderId}|${amount}`;
  if (seenSales.has(key)) continue;
  seenSales.add(key);
  sales.push({ date, amount, orderId });
}

const seenRefunds = new Set();
const refunds = [];
for (const row of refundRows) {
  const date = parseDate(row.Date ?? row.date);
  const amount = parseAmount(row.Amount ?? row.amount);
  const orderId = String(row['Order ID'] ?? row.orderId ?? row.order_id ?? '').trim();
  const typeRaw = String(row.Type ?? row.type ?? '').trim().toLowerCase();
  let type = null;
  if (typeRaw === 'refund') type = 'Refund';
  if (typeRaw === 'chargeback') type = 'Chargeback';
  if (!date || amount === null || !type) continue;
  const key = `${toDayKey(date)}|${orderId}|${type}|${amount}`;
  if (seenRefunds.has(key)) continue;
  seenRefunds.add(key);
  refunds.push({ date, amount, orderId, type, reason: row.Reason ?? row.reason ?? '' });
}

const inRange = (d, start, end) => d >= start && d <= end;

const currentSales = sales.filter((s) => inRange(s.date, currentWindowStart, currentWindowEnd));
const historicalSales = sales.filter((s) => inRange(s.date, historicalWindowStart, historicalWindowEnd));
const currentRefunds = refunds.filter((r) => inRange(r.date, currentWindowStart, currentWindowEnd));
const historicalRefunds = refunds.filter((r) => inRange(r.date, historicalWindowStart, historicalWindowEnd));

const sum = (arr) => arr.reduce((a, b) => a + b.amount, 0);
const currentSalesAmount = sum(currentSales);
const historicalSalesAmount = sum(historicalSales);
const currentRefundAmount = sum(currentRefunds.filter((r) => r.type === 'Refund'));
const currentChargebackAmount = sum(currentRefunds.filter((r) => r.type === 'Chargeback'));
const historicalRefundAmount = sum(historicalRefunds.filter((r) => r.type === 'Refund'));
const historicalChargebackAmount = sum(historicalRefunds.filter((r) => r.type === 'Chargeback'));
const currentRefundChargebackAmount = currentRefundAmount + currentChargebackAmount;
const historicalRefundChargebackAmount = historicalRefundAmount + historicalChargebackAmount;

const refundTransactionCount = currentRefunds.filter((r) => r.type === 'Refund').length;
const chargebackTransactionCount = currentRefunds.filter((r) => r.type === 'Chargeback').length;
const totalSalesTransactionCount = currentSales.length;
const historicalRefundTxnCount = historicalRefunds.filter((r) => r.type === 'Refund').length;
const historicalChargebackTxnCount = historicalRefunds.filter((r) => r.type === 'Chargeback').length;
const historicalSalesTxnCount = historicalSales.length;

const currentRatio = currentSalesAmount > 0
  ? round4((currentRefundChargebackAmount / currentSalesAmount) * 100)
  : null;
const historicalBaseline = historicalSalesAmount > 0
  ? round4((historicalRefundChargebackAmount / historicalSalesAmount) * 100)
  : null;
const currentTransactionRatio = totalSalesTransactionCount > 0
  ? round4(((refundTransactionCount + chargebackTransactionCount) / totalSalesTransactionCount) * 100)
  : null;
const historicalTransactionRatio = historicalSalesTxnCount > 0
  ? round4(((historicalRefundTxnCount + historicalChargebackTxnCount) / historicalSalesTxnCount) * 100)
  : null;

let status = 'NORMAL';
let anomaly = false;
let spikeMultiplier = null;

if (currentSalesAmount <= 0 || totalSalesTransactionCount === 0) {
  status = 'NO_CURRENT_SALES';
  anomaly = false;
} else if (
  historicalSalesAmount <= 0 ||
  historicalBaseline === null ||
  historicalBaseline === 0 ||
  historicalSalesTxnCount === 0
) {
  status = 'INSUFFICIENT_BASELINE';
  anomaly = false;
} else {
  spikeMultiplier = round4(currentRatio / historicalBaseline);
  anomaly = currentRatio >= historicalBaseline * thresholdMultiplier;
  status = anomaly ? 'ANOMALY' : 'NORMAL';
}

return [{
  json: {
    monitoringDate: toDayKey(monitoringDate),
    currentWindowStart: toDayKey(currentWindowStart),
    currentWindowEnd: toDayKey(currentWindowEnd),
    historicalWindowStart: toDayKey(historicalWindowStart),
    historicalWindowEnd: toDayKey(historicalWindowEnd),
    currentSalesAmount: round4(currentSalesAmount),
    currentRefundAmount: round4(currentRefundAmount),
    currentChargebackAmount: round4(currentChargebackAmount),
    currentRefundChargebackAmount: round4(currentRefundChargebackAmount),
    currentRatio,
    historicalSalesAmount: round4(historicalSalesAmount),
    historicalRefundAmount: round4(historicalRefundAmount),
    historicalChargebackAmount: round4(historicalChargebackAmount),
    historicalRefundChargebackAmount: round4(historicalRefundChargebackAmount),
    historicalBaseline,
    spikeMultiplier,
    thresholdMultiplier,
    anomaly,
    status,
    refundTransactionCount,
    chargebackTransactionCount,
    totalSalesTransactionCount,
    currentTransactionRatio,
    historicalTransactionRatio,
    diagnosticSummary: '',
  },
}];

const metrics = $('Calculate Refund Chargeback Metrics').first().json;
const gemini = $input.first().json;
const diagnosticSummary =
  gemini.mergedResponse ||
  gemini.content?.parts?.[0]?.text ||
  gemini.text ||
  gemini.output ||
  'Diagnostic summary unavailable.';

return [{
  json: {
    ...metrics,
    diagnosticSummary: String(diagnosticSummary).trim(),
  },
}];

